import sys, struct
sys.path.insert(0,'/workspace/src')
from xmwrite import note_name
b=open('/workspace/render/v14.xm','rb').read()
hsz,=struct.unpack('<I',b[60:64]); slen,restart,nch,npat=struct.unpack('<4H',b[64:72])
order=list(b[80:80+slen]); off=60+hsz; pats=[]
for p in range(npat):
    phl,pk,rows,psz=struct.unpack('<IBHH',b[off:off+9]); data=b[off+phl:off+phl+psz]; off+=phl+psz
    cells=[]; i=0
    while i<len(data):
        f=data[i]; i+=1
        if f&0x80:
            n=ins=v=e=pr=0
            if f&1: n=data[i]; i+=1
            if f&2: ins=data[i]; i+=1
            if f&4: v=data[i]; i+=1
            if f&8: e=data[i]; i+=1
            if f&16: pr=data[i]; i+=1
        else:
            n,ins,v,e,pr=f,data[i],data[i+1],data[i+2],data[i+3]; i+=4
        cells.append((n,ins,v,e,pr))
    pats.append((rows,cells))
LOOPED={5,6,7,8,9,14,15}
names="K SN HH BS AR LD EC P1 P2 P3 HM FX ST HI L8 E2".split()
state=[None]*nch  # (inst, start_abs_row)
absrow=0; issues=[]
for pas in range(2):
    for p in order:
        rows,cells=pats[p]
        for r in range(rows):
            for c in range(nch):
                n,ins,v,e,pr=cells[r*nch+c]
                if n==97:
                    state[c]=None
                elif n and e!=3:
                    if ins: state[c]=(ins,absrow)
                    elif state[c]: state[c]=(state[c][0],absrow)
            absrow+=1
    # report sustained notes at end of pass
# second approach: compute durations of each looped note
state=[None]*nch; absrow=0; durs=[]
for pas in range(2):
    for p in order:
        rows,cells=pats[p]
        for r in range(rows):
            for c in range(nch):
                n,ins,v,e,pr=cells[r*nch+c]
                if n==97 or (n and e!=3):
                    if state[c]:
                        i0,r0=state[c]; durs.append((absrow-r0,c,i0,r0))
                    state[c]=(ins or (state[c][0] if state[c] else 0),absrow) if n!=97 else None
            absrow+=1
long=[d for d in durs if d[2] in LOOPED and d[0]>16]
print("looped-instrument notes lasting >16 rows:", len(long))
for d,c,i0,r0 in sorted(long)[-10:]:
    print(f"  ch {names[c]} inst {i0} from abs row {r0} (bar {(r0%640)//16} row {r0%16}) lasted {d} rows")
EOF"}

